graphql.query:
query GetOrg {
  viewer {
    organization {
      id
      name
    }
  }
}

query GetPlans {
  viewer {
    organization {
      plans(first: 50) {
        pageInfo { hasNextPage endCursor }
        edges {
          cursor
          node {
            name
            geometry { lat lng }
            location { lat lng }
            dateCreation
          }
        }
      }
    }
  }
}

query GetMap {
  node(id: "{{mapPlanId}}") {
    ... on MapPlan {
      name
      location { lat lng }
      imageCount
      status
    }
  }
}

mutation CreateProject($input: CreateProjectInput!) {
  createProject(input: $input) {
    project { id name }
  }
}

mutation CreateExport($input: CreateExportInput!) {
  createExport(input: $input) {
    export { id }
  }
}

query GetExports {
  node(id: "MapPlan:5a0de0835f1e08eaabc732bd") {
    ... on MapPlan {
      exports(first: 5) {
        edges {
          node {
            id
            user { username }
            parameters {
              projection
              merge
              contourInterval
              fileFormat
              resolution
            }
            status
            dateCreation
            downloadPath
          }
        }
      }
    }
  }
}

mutation UpdateIssue($input: UpdateIssueInput!) {
  updateIssue(input: $input) {
    issue { id title status }
  }
}

query GetImageCount {
  node(id: "{{mapPlanId}}") {
    ... on MapPlan {
      imageCount
    }
  }
}

mutation CreateExport($input: CreateExportInput!) {
  createExport(input: $input) {
    export { id }
  }
}
